import { test } from "node:test";
import assert from "node:assert/strict";
import type { Connection } from "../src/live/connection.ts";
import { Hub } from "../src/live/hub.ts";
import { Auctions, BidRejected } from "../src/live/auctions.ts";
import { attach } from "../src/live/gateway.ts";

class FakeConn implements Connection {
    readonly id: string;
    readyState: "open" | "closing" | "closed" = "open";
    bufferedAmount = 0;
    readonly frames: { type: string; [k: string]: unknown }[] = [];
    closedWith: number | null = null;

    constructor(id: string) {
        this.id = id;
    }
    send(frame: string) {
        if (this.readyState !== "open") throw new Error(`${this.id}: send on ${this.readyState} socket`);
        this.frames.push(JSON.parse(frame));
    }
    close(code: number) {
        this.closedWith = code;
        this.readyState = "closing";
    }
}

function setup(watchers: string[]) {
    const hub = new Hub({ maxBufferedBytes: 64 * 1024 });
    const auctions = new Auctions(hub, [
        { id: "vase", title: "Ming-style vase", highBidCents: 10_000, highBidder: null, minIncrementCents: 500, status: "open" },
        { id: "clock", title: "Carriage clock", highBidCents: 5_000, highBidder: null, minIncrementCents: 250, status: "open" },
    ]);
    const conns = watchers.map((id) => new FakeConn(id));
    const sessions = conns.map((c) => attach(hub, auctions, c, `bidder-${c.id}`));
    for (const s of sessions) s.onMessage(JSON.stringify({ op: "watch", lotId: "vase" }));
    const bidsSeen = () => Object.fromEntries(conns.map((c) => [c.id, c.frames.filter((f) => f.type === "bid").length]));
    return { hub, auctions, conns, sessions, bidsSeen };
}

test("an accepted bid reaches everyone watching the lot, and only them", () => {
    const { hub, auctions, conns } = setup(["a", "b", "c"]);
    const other = new FakeConn("x");
    hub.join(auctions.room("clock"), other);
    assert.equal(auctions.placeBid("vase", "bidder-a", 10_000), 3);
    for (const c of conns) assert.deepEqual(c.frames, [{ type: "bid", lotId: "vase", amountCents: 10_000, bidder: "bidder-a" }]);
    assert.deepEqual(other.frames, []);
});

test("rejected bids are answered to the bidder and never broadcast", () => {
    const { auctions, conns, sessions } = setup(["a", "b"]);
    auctions.placeBid("vase", "bidder-a", 10_000);
    sessions[1].onMessage(JSON.stringify({ op: "bid", lotId: "vase", amountCents: 10_200 }));
    assert.deepEqual(conns[1].frames.at(-1), { type: "error", message: "bid must be at least 10500" });
    assert.equal(conns[0].frames.length, 1);
    assert.throws(() => auctions.placeBid("nope", "bidder-a", 1), BidRejected);
});

test("a watcher who is too far behind is disconnected and everyone else still gets the bid", () => {
    const { hub, auctions, conns, bidsSeen } = setup(["a", "slow", "c", "d"]);
    conns[1].bufferedAmount = 200_000;
    const delivered = auctions.placeBid("vase", "bidder-a", 10_000);
    console.log("bids received per watcher:", bidsSeen(), "delivered =", delivered);
    assert.deepEqual(bidsSeen(), { a: 1, slow: 0, c: 1, d: 1 });
    assert.equal(conns[1].closedWith, 1013);
    assert.equal(hub.size("lot:vase"), 3);
});

test("watchers whose sockets already closed are pruned without hiding the bid from the next one", () => {
    const { hub, auctions, conns, bidsSeen } = setup(["gone", "b", "c"]);
    conns[0].readyState = "closed";
    assert.equal(auctions.placeBid("vase", "bidder-b", 10_000), 2);
    assert.deepEqual(bidsSeen(), { gone: 0, b: 1, c: 1 });
    assert.equal(hub.size("lot:vase"), 2);
});

test("several slow watchers in a row are all disconnected in one broadcast", () => {
    const { hub, auctions, conns, bidsSeen } = setup(["s1", "s2", "s3", "ok"]);
    for (const c of conns.slice(0, 3)) c.bufferedAmount = 1_000_000;
    auctions.placeBid("vase", "bidder-ok", 10_000);
    assert.deepEqual(conns.map((c) => c.closedWith), [1013, 1013, 1013, null]);
    assert.deepEqual(bidsSeen(), { s1: 0, s2: 0, s3: 0, ok: 1 });
    assert.equal(hub.size("lot:vase"), 1);
});

test("unwatching or closing the socket stops further updates", () => {
    const { hub, auctions, conns, sessions } = setup(["a", "b", "c"]);
    sessions[0].onMessage(JSON.stringify({ op: "unwatch", lotId: "vase" }));
    sessions[1].onClose();
    auctions.placeBid("vase", "bidder-c", 10_000);
    assert.deepEqual(conns.map((c) => c.frames.length), [0, 0, 1]);
    assert.equal(hub.size("lot:vase"), 1);
    sessions[2].onMessage("{not json");
    assert.equal(conns[2].closedWith, 1008);
    assert.equal(hub.size("lot:vase"), 0);
});

test("the hammer message reaches every healthy watcher", () => {
    const { auctions, conns } = setup(["a", "b", "lagging", "d", "e"]);
    auctions.placeBid("vase", "bidder-d", 12_000);
    conns[2].bufferedAmount = 100_000;
    assert.equal(auctions.hammer("vase"), 4);
    const sold = conns.map((c) => c.frames.some((f) => f.type === "sold" && f.winner === "bidder-d"));
    assert.deepEqual(sold, [true, true, false, true, true]);
    assert.throws(() => auctions.placeBid("vase", "bidder-a", 20_000), /closed/);
});
